import axiosClient from "./axiosClient";
import Cookies from "js-cookie";

const HistoryAPI = {
  // Lấy danh sách lịch sử đơn hàng, có thể truyền query (param) nếu cần
  getHistoryAPI: (query) => {
    const url = `/orders`;
    const token = Cookies.get("tokena"); // Lấy token từ cookie
    return axiosClient.get(url, {
      params: query, // Thêm query vào params nếu có
      headers: {
        "X-Role": "admin", // Thêm header X-Role là 'admin' để phân biệt vai trò
        Authorization: `Bearer ${token}`, // Thêm token vào header
      },
      withCredentials: true,
    });
  },

  // Lấy chi tiết đơn hàng theo id
  getDetail: (id) => {
    const url = `/orders/${id}`;
    const token = Cookies.get("tokena"); // Lấy token từ cookie
    return axiosClient.get(url, {
      headers: {
        "X-Role": "admin", // Thêm header X-Role là 'admin' để phân biệt vai trò
        Authorization: `Bearer ${token}`, // Thêm token vào header
      },
      withCredentials: true,
    });
  },

  // Lấy tất cả các đơn hàng (có thể sử dụng khi không cần query)
  getAll: () => {
    const url = `/orders`;
    const token = Cookies.get("tokena"); // Lấy token từ cookie
    return axiosClient.get(url, {
      headers: {
        "X-Role": "admin", // Thêm header X-Role là 'admin' để phân biệt vai trò
        Authorization: `Bearer ${token}`, // Thêm token vào header
      },
      withCredentials: true,
    });
  },
};

export default HistoryAPI;
